import {questions, sections, evaluate} from './questions.js';
const $ = s => document.querySelector(s);
const app = $('#app');
const key = 'mehnat-bilim-v1';
const letters = ['A','B','C','D'];
const empty = () => ({answers:{},flags:[],current:0});
const isAttempt = a => a && typeof a === 'object' && a.answers && typeof a.answers==='object' && !Array.isArray(a.answers) && Object.entries(a.answers).every(([k,v]) => /^([1-9]|[12][0-9]|30)$/.test(k) && letters.includes(v)) && Array.isArray(a.flags) && a.flags.every(n=>Number.isInteger(n)&&n>=1&&n<=30) && Number.isInteger(a.current) && a.current>=0 && a.current<30;
let data={active:null,history:[]}, storageAvailable=true, view='home', result=null, filter='all';
try {
 const raw=JSON.parse(localStorage.getItem(key)||'null');
 if(raw && isAttempt(raw.active)) data.active=raw.active;
 if(raw && Array.isArray(raw.history)) data.history=raw.history.filter(h=>isAttempt(h)&&typeof h.id==='string'&&typeof h.finished==='string'&&Number.isFinite(Date.parse(h.finished)));
 localStorage.setItem(key,JSON.stringify(data));
} catch {storageAvailable=false;}
function save(){try{localStorage.setItem(key,JSON.stringify(data));storageAvailable=true;}catch{storageAvailable=false;} updateChrome();}
function updateChrome(){ $('#storage-warning').hidden=storageAvailable;$('#history-count').textContent=data.history.length; }
const answered = () => Object.keys(data.active?.answers||{}).length;
const escape = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date = value => new Intl.DateTimeFormat('uz-Latn',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));
const gradeRows = `<div class="grade-row"><strong><i class="dot"></i>A’lo (5)</strong><span>26–30 ball</span></div><div class="grade-row"><strong><i class="dot"></i>Yaxshi (4)</strong><span>22–25 ball</span></div><div class="grade-row"><strong><i class="dot"></i>Qoniqarli (3)</strong><span>17–21 ball</span></div><div class="grade-row"><strong><i class="dot"></i>Qoniqarsiz (2)</strong><span>0–16 ball</span></div>`;
const legal = `<details class="legal"><summary>Huquqiy asos va muhim eslatma</summary><p>Testlar O‘zbekiston Respublikasining mehnat qonunchiligi va mehnatni muhofaza qilishga oid normativ-huquqiy hujjatlarining umumiy huquqiy tamoyillari asosida tuzildi. Nazorat organlarining amaldagi rasmiy nomlari va vakolatlari bo‘yicha so‘nggi normativ o‘zgarishlar alohida tekshirilishi lozim.</p><p>Ushbu testlar 4-kurs talabalarining nazariy bilimlarini, huquqiy tahlil qilish qobiliyatini va mehnat muhofazasiga oid amaliy vaziyatlarda qaror qabul qilish ko‘nikmalarini baholashga mo‘ljallangan. Javoblar kaliti asl nusxadagidek saqlandi, qonunchilikka muvofiqligi alohida tekshirilmadi.</p></details>`;
function navigate(next){view=next;render();window.scrollTo({top:0});app.querySelector('h1')?.focus({preventScroll:true});}
function render(){updateChrome(); if(view==='home')home(); else if(view==='test')test();else if(view==='history')history();else results();}
function home(){app.innerHTML=`<section class="hero"><div><div class="eyebrow">Bilimingizni sinab ko‘ring</div><h1>Mehnat muhofazasi.<br><span>Ishonchli bilim —<br>xavfsiz kelajak.</span></h1><p>Mehnat muhofazasining huquqiy va tashkiliy asoslarini nazorat qiluvchi organlar bo‘yicha bilimingizni tekshiring.</p><div class="hero-actions"><button class="button primary" data-action="start">${data.active?'Testni davom ettirish':'Testni boshlash'} <span aria-hidden="true">→</span></button>${data.active?'<button class="button secondary" data-action="fresh">Yangidan boshlash</button>':''}</div><p class="hero-caption"><span aria-hidden="true">✓</span> ${data.active?`${answered()} / 30 savolga javob berilgan · Saqlangan urinish`:'Ro‘yxatdan o‘tish shart emas · Vaqt cheklanmagan'}</p></div><aside class="overview" aria-label="Test haqida"><div class="overview-top"><div class="overview-icon" aria-hidden="true">▤</div><div><h2>Bilim sinovi</h2><p>4-kurs universitet talabalari uchun</p></div></div><div class="stats"><div><strong>30</strong><small>ta savol</small></div><div><strong>4</strong><small>ta javob varianti</small></div><div><strong>30</strong><small>maksimal ball</small></div></div><div class="overview-bottom"><span>Murakkablik darajasi</span><span class="pill">Yuqori</span></div></aside></section><section><div class="section-heading"><h2>Test nimalarni qamrab oladi?</h2><span>4 bo‘lim · 30 savol</span></div><div class="topic-grid">${sections.map((s,i)=>`<article class="topic"><span class="topic-number">0${i+1}</span><span class="topic-icon" aria-hidden="true">${['§','▥','⚙','⚖'][i]}</span><h3>${s}</h3><p>${['1–6-savollar · 6 ta','7–15-savollar · 9 ta','16–22-savollar · 7 ta','23–30-savollar · 8 ta'][i]}</p></article>`).join('')}</div></section><section class="lower"><div class="rules"><h2>Boshlashdan oldin</h2><div class="rule"><b aria-hidden="true">✓</b><span>Har bir savolda faqat bitta to‘g‘ri javobni tanlang.</span></div><div class="rule"><b aria-hidden="true">✓</b><span>Javoblarni o‘zgartirishingiz va savollarga qaytishingiz mumkin.</span></div><div class="rule"><b aria-hidden="true">✓</b><span>Natija va to‘g‘ri javoblar test yakunida ko‘rsatiladi.</span></div><div class="rule"><b aria-hidden="true">✓</b><span>Javoblar shu brauzerda avtomatik saqlanadi.</span></div></div><div class="grading"><h2>Bilimingiz qanday baholanadi?</h2>${gradeRows}</div></section>${legal}`;const h=app.querySelector('h1');h.tabIndex=-1;}
function start(){if(!data.active)data.active=empty();save();navigate('test');}
function fresh(){if(data.active){$('#dialog-title').textContent='Yangidan boshlaysizmi?';$('#dialog-description').textContent='Tugallanmagan urinishdagi javoblaringiz o‘chiriladi. Avvalgi yakunlangan natijalar saqlanadi.';$('#confirm-finish').textContent='Yangidan boshlash';pending='restart';$('#finish-dialog').showModal();}else start();}
function test(){if(!data.active){navigate('home');return;}const a=data.active,q=questions[a.current];app.innerHTML=`<div class="page-top"><div><div class="eyebrow">Bilim sinovi</div><h1 tabindex="-1">Mehnat muhofazasi</h1></div><span class="saved" role="status">${storageAvailable?'✓ Javoblar saqlanmoqda':'Saqlash imkoni yo‘q'}</span></div><div class="test-layout"><section class="card question-card" aria-labelledby="question-title"><div class="question-top"><span>${sections[q.section]}</span><span>${q.id} / 30</span></div><div class="progress" role="progressbar" aria-label="Javob berilgan savollar" aria-valuenow="${answered()}" aria-valuemin="0" aria-valuemax="30"><div style="width:${answered()/30*100}%"></div></div><h2 id="question-title" tabindex="-1">${q.id}. ${q.text}</h2><fieldset class="options"><legend class="sr-only">Javobni tanlang</legend>${q.options.map((o,i)=>`<label class="option ${a.answers[q.id]===letters[i]?'selected':''}"><input type="radio" name="answer" value="${letters[i]}" ${a.answers[q.id]===letters[i]?'checked':''}><span class="letter" aria-hidden="true">${letters[i]}</span><span>${o}</span></label>`).join('')}</fieldset><button class="mark" data-action="flag" aria-pressed="${a.flags.includes(q.id)}"><span aria-hidden="true">${a.flags.includes(q.id)?'★':'☆'}</span> Keyinroq qaytish${a.flags.includes(q.id)?' · belgilangan':''}</button><div class="question-actions"><button class="button secondary" data-action="previous" ${a.current===0?'disabled':''}>← Oldingi</button>${a.current<29?'<button class="button primary" data-action="next">Keyingi →</button>':'<button class="button primary" data-action="finish">Testni yakunlash ✓</button>'}</div></section><aside class="card sidebar"><h2>Savollar xaritasi</h2><div class="number-grid">${questions.map(n=>`<button class="number ${a.answers[n.id]?'answered':''} ${a.current===n.id-1?'current':''} ${a.flags.includes(n.id)?'flagged':''}" data-jump="${n.id-1}" ${a.current===n.id-1?'aria-current="step"':''} aria-label="${n.id}-savol${a.answers[n.id]?', javob berilgan':', javobsiz'}${a.flags.includes(n.id)?', keyinroq qaytish uchun belgilangan':''}">${n.id}${a.answers[n.id]?'<span class="sr-only"> ✓</span>':''}</button>`).join('')}</div><div class="legend"><span><i class="blue"></i>Joriy savol</span><span><i class="pale"></i>Javob berilgan ✓</span><span><i></i>Javobsiz</span><span><i class="star">★</i>Keyinroq qaytish</span></div><button class="button secondary" data-action="finish">Testni yakunlash</button><p class="sidebar-note">${answered()} / 30 savolga javob berildi.<br>Har bir to‘g‘ri javob — 1 ball.</p></aside></div>`;}
function jump(index){data.active.current=index;save();test();$('#question-title').focus();}
function history(){app.innerHTML=`<div class="page-top"><div><div class="eyebrow">Shaxsiy rivojlanish</div><h1 tabindex="-1">Natijalarim</h1></div><button class="button primary" data-action="start">${data.active?'Davom ettirish':'Testni boshlash'} →</button></div><p class="sidebar-note" style="margin:0 0 20px">Natijalar faqat shu brauzerda saqlanadi. Brauzer ma’lumotlari tozalansa, tarix ham o‘chadi.</p><div class="history-list">${data.history.length?data.history.map(h=>{const r=evaluate(h.answers);return `<article class="card history-item"><div><h2>${r.label} (${r.grade})</h2><p>${escape(date(h.finished))}</p></div><div class="history-score">${r.score}<span style="font-size:13px;color:var(--muted)"> / 30</span></div><button class="button secondary" data-result="${escape(h.id)}">Natijani ko‘rish →</button></article>`;}).join(''):'<section class="card empty"><div class="topic-icon" style="margin:auto" aria-hidden="true">▤</div><h2>Hozircha natijalar yo‘q</h2><p>Birinchi testni yakunlang.<br>Natijangiz va javoblar tahlili shu yerda saqlanadi.</p></section>'}</div>`;}
function results(){if(!result){navigate('history');return;}const r=evaluate(result.answers);const qs=questions.filter(q=>filter==='all'||result.answers[q.id]!==q.correct);app.innerHTML=`<div class="page-top"><div><div class="eyebrow">Test yakunlandi</div><h1 tabindex="-1">Sizning natijangiz</h1></div><button class="button secondary" data-action="fresh">Qayta topshirish ↻</button></div><section class="card result-hero"><div class="score-ring" style="--progress:${r.percent}%"><div class="score-inner"><strong>${r.score}<span> / 30</span></strong><span>${r.percent}% natija</span></div></div><div><span class="pill">Baho: ${r.grade}</span><h2>${r.label}${r.grade>=4?'!':''}</h2><p>${r.grade>=4?'Yaxshi natija! Bilimingizni yanada mustahkamlash uchun javoblar tahlilini ko‘rib chiqing.':'Har bir urinish — o‘rganish imkoniyati. Javoblar tahlilini ko‘rib chiqing va yana urinib ko‘ring.'}<br>${escape(date(result.finished))}</p><div class="result-stats"><div class="correct-text"><strong>${r.score}</strong>To‘g‘ri</div><div class="wrong-text"><strong>${r.wrong}</strong>Noto‘g‘ri</div><div><strong>${r.skipped}</strong>Javobsiz</div></div></div></section><div class="review-toolbar"><h2>Javoblar tahlili</h2><div class="filter" aria-label="Tahlil filtri"><button data-filter="all" aria-pressed="${filter==='all'}">Barchasi (30)</button><button data-filter="errors" aria-pressed="${filter==='errors'}">Xatolar va javobsiz (${30-r.score})</button></div></div><div>${qs.length?qs.map(q=>{const answer=result.answers[q.id],ok=answer===q.correct;return `<article class="card review-card"><span class="review-status ${ok?'correct-text':'wrong-text'}">${ok?'✓ TO‘G‘RI':answer?'✕ NOTO‘G‘RI':'○ JAVOBSIZ'} · ${q.id}-SAVOL</span><h3>${q.text}</h3>${q.options.map((o,i)=>{const l=letters[i],right=l===q.correct,chosen=l===answer;return `<div class="review-option ${right?'right':chosen?'wrong':''}">${right||chosen?`<strong>${right?'✓ To‘g‘ri javob':''}${right&&chosen?' · Sizning javobingiz':!right&&chosen?'✕ Sizning javobingiz':''}</strong>`:''}${l}) ${o}</div>`;}).join('')}</article>`;}).join(''):'<section class="card empty"><h2>Barcha javoblar to‘g‘ri!</h2><p>Ajoyib! Siz 30 savolning barchasiga to‘g‘ri javob berdingiz.</p></section>'}</div>${legal}`;}
let pending='finish';
function askFinish(){pending='finish';const skipped=30-answered();$('#dialog-title').textContent='Testni yakunlaysizmi?';$('#dialog-description').textContent=skipped?`${skipped} ta savol javobsiz qoldi. Javobsiz savollar uchun 0 ball beriladi. Savollarga qaytishingiz yoki hozir yakunlashingiz mumkin.`:'Barcha 30 ta savolga javob berdingiz. Yakunlangandan so‘ng bu urinishdagi javoblarni o‘zgartirib bo‘lmaydi.';$('#confirm-finish').textContent='Yakunlash';$('#finish-dialog').showModal();}
$('#cancel-finish').onclick=()=>$('#finish-dialog').close();
$('#confirm-finish').onclick=()=>{ $('#finish-dialog').close();if(pending==='restart'){data.active=empty();save();navigate('test');return;}if(!data.active)return;result={...data.active,answers:{...data.active.answers},flags:[...data.active.flags],finished:new Date().toISOString(),id:crypto.randomUUID?crypto.randomUUID():String(Date.now())};data.history.unshift(result);data.active=null;save();filter='all';navigate('result');};
$('#home-nav').onclick=()=>navigate('home');$('#brand').onclick=e=>{e.preventDefault();navigate('home');};$('#history-nav').onclick=()=>navigate('history');
app.addEventListener('change',e=>{if(e.target.name==='answer'&&data.active&&letters.includes(e.target.value)){const q=questions[data.active.current];data.active.answers[q.id]=e.target.value;save();test();app.querySelector(`input[value="${e.target.value}"]`).focus();}});
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.jump!==undefined){jump(Number(b.dataset.jump));return;}if(b.dataset.result){result=data.history.find(h=>h.id===b.dataset.result);filter='all';navigate('result');return;}if(b.dataset.filter){filter=b.dataset.filter;const y=window.scrollY;results();app.querySelector(`[data-filter="${filter}"]`).focus({preventScroll:true});window.scrollTo(0,y);return;}switch(b.dataset.action){case 'start':start();break;case 'fresh':fresh();break;case 'next':jump(Math.min(29,data.active.current+1));break;case 'previous':jump(Math.max(0,data.active.current-1));break;case 'flag':{const id=data.active.current+1;data.active.flags=data.active.flags.includes(id)?data.active.flags.filter(n=>n!==id):[...data.active.flags,id];save();test();$('.mark').focus();break;}case 'finish':askFinish();break;}});
render();
